export const MINNA_VOCABULARY: VocabularyItem[] = Object.entries(RAW).flatMap(([lesson, items]) => {
  const n = Number(lesson);
  return items.map(([hiragana, kanji, meaning], i) => ({
    id: `minna_l${n}_${i + 1}`,
    kanji: kanji || hiragana,
    hiragana,
    meaning,
    exampleSentence: '',
    exampleTranslation: '',
    level: n <= 25 ? 'N5' : 'N4',
    lessonId: `minna_l${n}`,
    lessonName: `Bài ${n}`,
    lessonTitleJp: `第${n}課`,
    chapter: n <= 25 ? 'Minna no Nihongo I' : 'Minna no Nihongo II',
    curriculum: 'minna',
    originalNumber: i + 1,
  }));
});
